/**
 * Disposable, test-only Nostr signer for the fake-money demo.
 *
 * The secret is generated by WebCrypto, held only in this page's closure, and
 * never exported, logged, persisted, or sent to the server. Reloading creates
 * no identity automatically. This is a convenience for teammates without a
 * NIP-07 extension, not an account or production key-management feature.
 */
import { secp256k1, schnorr } from "@noble/curves/secp256k1.js";
import { sha256 } from "@noble/hashes/sha2.js";
import { bytesToHex, hexToBytes } from "@noble/hashes/utils.js";
import { demoFridayFundingKeyAuthorizationDigest, type DemoFridayFundingKeyAuthorizationTermsV1 } from "./demo-friday-browser-funding-authorization";
import {
	demoMaintainerTemplateBundleDigest,
	validateDemoMaintainerExactBranchTemplate,
	type DemoMaintainerExactBranchTemplate,
	type DemoMaintainerPackageAuthorization,
} from "./demo-maintainer-offline";
import type { DemoDispositionRole } from "./demo-sigall-settlement";

const TERMINAL_ACK_CONTEXT = new TextEncoder().encode("PLEBEIAN_FRIDAY_COCO_TERMINAL_ACK_V1");

type UnsignedEvent = { kind: number; created_at: number; tags: string[][]; content: string };
type SignedEvent = UnsignedEvent & { id: string; pubkey: string; sig: string };

function freshSecret(): Uint8Array {
	for (;;) {
		const candidate = globalThis.crypto.getRandomValues(new Uint8Array(32));
		try {
			secp256k1.getPublicKey(candidate, true);
			return candidate;
		} catch {
			// Uniform WebCrypto output almost never lands outside the scalar range.
		}
	}
}

async function digest(text: string): Promise<Uint8Array> {
	return new Uint8Array(await globalThis.crypto.subtle.digest("SHA-256", new TextEncoder().encode(text)));
}

function createDisposableSigner(): { getPublicKey(): Promise<string>; signEvent(event: UnsignedEvent): Promise<SignedEvent> } {
	const secret = freshSecret();
	const pubkey = bytesToHex(schnorr.getPublicKey(secret));
	return {
		async getPublicKey(): Promise<string> { return pubkey; },
		async signEvent(event: UnsignedEvent): Promise<SignedEvent> {
			const canonical = JSON.stringify([0, pubkey, event.created_at, event.kind, event.tags, event.content]);
			const hash = await digest(canonical);
			return { ...event, id: bytesToHex(hash), pubkey, sig: bytesToHex(schnorr.sign(hash, secret)) };
		},
	};
}

Object.defineProperty(globalThis, "plebeianCreateDemoSigner", {
	configurable: false,
	enumerable: false,
	writable: false,
	value: createDisposableSigner,
});

/**
 * A different key for Cashu SIG_ALL messages. This is never the Nostr identity
 * and is never handed to NIP-07. The page-global factory remains disposable;
 * the exported constructor only reopens fake-money operation keys from the
 * browser-private journal. The narrow Cashu method constructs Nutshell's
 * SIG_ALL message locally and never accepts a caller-supplied Cashu digest.
 */
export interface DemoFridayPaymentSigner {
	getPublicKey(): Promise<string>;
	signCashuSigAllPackage(value: { inputs: Array<{ secret: string }>; outputs: Array<{ B_: string }> }): Promise<{ digest: string; signature: string }>;
	signFridayTemplateAuthorization(value: {
		operationId: string;
		role: DemoDispositionRole;
		template: DemoMaintainerExactBranchTemplate;
	}): Promise<{ packageDigest: string; signature: string }>;
	signFridayBundleAuthorization(value: {
		operationId: string;
		preparedAt: number;
		winner: DemoMaintainerExactBranchTemplate;
		refund: DemoMaintainerExactBranchTemplate;
		actorWinnerAuthorization: DemoMaintainerPackageAuthorization;
		actorReturnAuthorization: DemoMaintainerPackageAuthorization;
	}): Promise<{ bundleDigest: string; signature: string }>;
	signFridayFundingKeyAuthorization(actor: string, value: DemoFridayFundingKeyAuthorizationTermsV1): Promise<string>;
	signRecipientCapability(value: { digest: string; recipientPublicKey: string; operationId: string; role: DemoDispositionRole }): Promise<string>;
	signTerminalAck(value: { noticeDigest: string; importReceiptCanonical: string; recipientPublicKey: string }): Promise<string>;
	dispose(): void;
}

/** Reopen one browser-persisted fake-money payment/refund key without exporting it to the server. */
export function createDemoFridayPaymentSignerFromSecret(input: Uint8Array): DemoFridayPaymentSigner {
	if (input.length !== 32) throw new Error("Friday payment signer secret must be 32 bytes");
	const secret = Uint8Array.from(input);
	try { secp256k1.getPublicKey(secret, true); }
	catch { secret.fill(0); throw new Error("Friday payment signer secret is invalid"); }
	const publicKey = bytesToHex(secp256k1.getPublicKey(secret, true));
	let disposed = false;
	const active = (): void => { if (disposed) throw new Error("Friday payment signer was disposed"); };
	return {
		async getPublicKey(): Promise<string> { active(); return publicKey; },
		async signCashuSigAllPackage(value): Promise<{ digest: string; signature: string }> {
			active();
			if (value === null || typeof value !== "object" || !Array.isArray(value.inputs) || value.inputs.length === 0
				|| !Array.isArray(value.outputs) || value.outputs.length === 0 || value.inputs.length > 32 || value.outputs.length > 64
				|| value.inputs.some((input) => input === null || typeof input !== "object" || typeof input.secret !== "string" || input.secret.length < 1 || input.secret.length > 4096)
				|| value.outputs.some((output) => output === null || typeof output !== "object" || !/^(?:02|03)[0-9a-f]{64}$/.test(output.B_))) {
				throw new Error("Cashu SIG_ALL package shape is invalid");
			}
			const source = [...value.inputs.map((input) => input.secret), ...value.outputs.map((output) => output.B_)].join("");
			const digest = bytesToHex(sha256(new TextEncoder().encode(source)));
			return { digest, signature: bytesToHex(schnorr.sign(hexToBytes(digest), secret)) };
		},
		async signFridayTemplateAuthorization(value): Promise<{ packageDigest: string; signature: string }> {
			active();
			if (value === null || typeof value !== "object" || value.operationId !== value.template.operationId
				|| value.role !== value.template.role || value.template.bidderPublicKey !== publicKey) {
				throw new Error("Friday template authorization differs from the operation payment key");
			}
			const template = validateDemoMaintainerExactBranchTemplate(value.template, value.role);
			return {
				packageDigest: template.templateDigest,
				signature: bytesToHex(schnorr.sign(hexToBytes(template.templateDigest), secret)),
			};
		},
		async signFridayBundleAuthorization(value): Promise<{ bundleDigest: string; signature: string }> {
			active();
			if (value === null || typeof value !== "object" || value.operationId !== value.winner.operationId
				|| value.operationId !== value.refund.operationId || value.winner.bidderPublicKey !== publicKey
				|| value.refund.bidderPublicKey !== publicKey || value.winner.role !== "winner_settlement"
				|| value.refund.role !== "refund" || !Number.isSafeInteger(value.preparedAt) || value.preparedAt < 1) {
				throw new Error("Friday bundle authorization differs from the operation payment key");
			}
			const winner = validateDemoMaintainerExactBranchTemplate(value.winner, "winner_settlement");
			const refund = validateDemoMaintainerExactBranchTemplate(value.refund, "refund");
			for (const [authorization, template] of [
				[value.actorWinnerAuthorization, winner], [value.actorReturnAuthorization, refund],
			] as const) {
				if (!("schema" in authorization)
					|| authorization.schema !== "COCO_DEMO_PAYMENT_KEY_PACKAGE_AUTHORIZATION_V1"
					|| authorization.paymentPublicKey !== publicKey
					|| authorization.packageDigest !== template.templateDigest
					|| !schnorr.verify(hexToBytes(authorization.signature), hexToBytes(template.templateDigest), hexToBytes(publicKey.slice(2)))) {
					throw new Error("Friday bundle contains an invalid role-bound package authorization");
				}
			}
			const bundleDigest = demoMaintainerTemplateBundleDigest({
				preparedAt: value.preparedAt, winner, refund,
				actorWinnerAuthorization: value.actorWinnerAuthorization,
				actorReturnAuthorization: value.actorReturnAuthorization,
			});
			return { bundleDigest, signature: bytesToHex(schnorr.sign(hexToBytes(bundleDigest), secret)) };
		},
		async signFridayFundingKeyAuthorization(actor, value): Promise<string> {
			active();
			const digest = demoFridayFundingKeyAuthorizationDigest(actor, value);
			return bytesToHex(schnorr.sign(hexToBytes(digest), secret));
		},
		async signRecipientCapability(value): Promise<string> {
			active();
			if (!/^[0-9a-f]{64}$/.test(value.digest) || value.recipientPublicKey !== publicKey
				|| !/^[A-Za-z0-9_-]{1,160}$/.test(value.operationId)
				|| !["winner_settlement", "refund"].includes(value.role)) {
				throw new Error("Friday recipient capability differs from the persisted operation key");
			}
			return bytesToHex(schnorr.sign(hexToBytes(value.digest), secret));
		},
		async signTerminalAck(value): Promise<string> {
			active();
			if (!/^[0-9a-f]{64}$/.test(value.noticeDigest) || value.recipientPublicKey !== publicKey
				|| typeof value.importReceiptCanonical !== "string" || value.importReceiptCanonical.length < 2
				|| value.importReceiptCanonical.length > 4096) {
				throw new Error("Friday terminal acknowledgement differs from the operation recipient key");
			}
			const material = new Uint8Array(TERMINAL_ACK_CONTEXT.length + 32 + new TextEncoder().encode(value.importReceiptCanonical).length);
			material.set(TERMINAL_ACK_CONTEXT, 0);
			material.set(hexToBytes(value.noticeDigest), TERMINAL_ACK_CONTEXT.length);
			material.set(new TextEncoder().encode(value.importReceiptCanonical), TERMINAL_ACK_CONTEXT.length + 32);
			// A retry after a lost acknowledgement must be byte-identical.
			return bytesToHex(schnorr.sign(sha256(material), secret, new Uint8Array(32)));
		},
		dispose(): void { if (!disposed) { disposed = true; secret.fill(0); } },
	};
}

function createDisposablePaymentSigner(): DemoFridayPaymentSigner {
	const secret = freshSecret();
	try { return createDemoFridayPaymentSignerFromSecret(secret); }
	finally { secret.fill(0); }
}

Object.defineProperty(globalThis, "plebeianCreateDemoPaymentSigner", {
	configurable: false,
	enumerable: false,
	writable: false,
	value: createDisposablePaymentSigner,
});

